// updateHostsBlock writes or replaces the zapret block, leaving every other
// entry (including the SmartDNS block) untouched.
func updateHostsBlock(path string) error {
	existing, _ := os.ReadFile(path)
	cleaned := stripHostsBlock(string(existing))

	var sb strings.Builder
	sb.WriteString(strings.TrimRight(cleaned, "\n"))
	if sb.Len() > 0 {
		sb.WriteString("\n\n")
	}
	sb.WriteString(hostsBlockHeader)
	sb.WriteString("\n")
	for _, line := range bypassHosts {
		sb.WriteString(line)
		sb.WriteString("\n")
	}
	sb.WriteString(hostsBlockFooter)
	sb.WriteString("\n")

	return os.WriteFile(path, []byte(sb.String()), 0o644)
}

// removeHostsBlock drops the zapret block on uninstall.
func removeHostsBlock(path string) error {
	existing, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	return os.WriteFile(path, []byte(stripHostsBlock(string(existing))), 0o644)
}

func stripHostsBlock(content string) string {
	idx := strings.Index(content, hostsBlockMarker)
	if idx == -1 {
		return content
	}

	start := strings.LastIndex(content[:idx], "# ===")
	if start == -1 {
		start = idx
	}

	rel := strings.Index(content[idx:], hostsBlockFooter)
	if rel == -1 {
		return content[:start]
	}
	end := idx + rel + len(hostsBlockFooter)
	if end < len(content) && content[end] == '\n' {
		end++
	}

	before := strings.TrimRight(content[:start], "\n")
	after := strings.TrimLeft(content[end:], "\n")

	if before != "" && after != "" {
		return before + "\n" + after
	}
	if before != "" {
		return before + "\n"
	}
	return after
}
